expect fun platformIO(): CoroutineDispatcher
expect suspend fun platformSynchronization(topic:Int, records:List<String>,emit:(String)->Unit)
expect fun platformTeachingSource(topic:Int):String
data class LabEvent(val sequence:Int, val message:String)
data class FileSummary(val name:String, val bytes:Long, val lines:Int)
data class Readiness(val ready:Boolean, val profile:String)
data class Demo(val id:Int,val module:String,val title:String,val source:String,val run:suspend DemoRun.()->Unit)
class DemoRun(records:List<String>, private val sink:(LabEvent)->Unit, val networkEvents:Flow<String> = emptyFlow()) {
    val records:List<String> = records.toList()
    private val sequence=MutableStateFlow(0)
    // Events from different dispatchers go through a bounded SharedFlow at the UI boundary.
    fun event(message:String) { sink(LabEvent(sequence.updateAndGet { it+1 },message.take(500))) }
}
suspend fun suspendingCount(records:List<String>):Int { delay(25); return records.size }
